  const cfg = {};
  for (const it of $(nodeName).all()) {
    if (it.json.key) cfg[String(it.json.key).trim()] = String(it.json.value ?? '').trim();
  }
  return cfg;
};

const str = (v) => String(v ?? '').trim();
const cleanCaption = (s) => String(s ?? '').replace(/[—–]/g, '-');
const mediaList = (s) => str(s).split(/[\s,]+/).filter(Boolean);
const isVideoUrl = (u) => /\.(mp4|mov|m4v|webm)(\?|#|$)/i.test(u) || /\/video\/upload\//.test(u);

/** Approved = explicit approval stamp, or a standing "auto" approval. */
const isApproved = (r) => str(r.approval_mode) === 'auto' || str(r.approved_at) !== '';

/** Small JPEG still of a Cloudinary image/video (Telegram previews, thumbnails). */
const cloudinaryStill = (url, width = 1080) => {
  const m = /^(https:\/\/res\.cloudinary\.com\/[^/]+)\/(image|video)\/upload\/(.+)$/.exec(url || '');
  if (!m) return url || '';
  if (m[2] === 'video') return `${m[1]}/video/upload/so_1,w_${width},c_limit/${m[3].replace(/\.[a-z0-9]+(\?.*)?$/i, '')}.jpg`;
  return `${m[1]}/image/upload/w_${width},c_limit,q_auto,f_jpg/${m[3]}`;
};

const randomRef = () => Math.random().toString(36).slice(2, 8);
// ---- end shared helpers ----
// Builds the draft row. Uses the first AI variant when available and falls
// back to the Telegram text if the AI call was skipped or failed.
const req = $('Build Caption Request').first().json;
const ai = $json && Array.isArray($json.variants) ? $json : null;

const compose = (v) => {
  const tags = [...new Set((v.hashtags || []).map((h) => '#' + String(h).replace(/^#+/, '').trim()).filter((h) => h.length > 1))];
  const body = cleanCaption(v.caption).trim();
  return tags.length ? `${body}\n\n${tags.slice(0, 30).join(' ')}` : body;
};

const variants = ai ? ai.variants.filter((v) => str(v.caption)) : [];
const caption = variants.length ? compose(variants[0]) : req.fallback_caption;
const now = toLocal();
const day = now.slice(0, 10);

const errorOf = (j) => (j && (typeof j.error === 'string' ? j.error : j.error && j.error.message)) || '';
const aiError = req.use_ai && !variants.length ? str(errorOf($json)) || 'no response' : '';
const alternatives = variants.slice(1).map((v, i) => `— גרסה ${i + 2} (${str(v.angle)}):\n${compose(v)}`).join('\n\n');

return [{
  json: {
    id: `${day}-${Math.floor(Math.random() * 36 ** 4).toString(36).padStart(4, '0')}`,
    type: req.is_video ? 'REEL' : 'POST',
    media_urls: req.media_url,
    caption,
    approval_mode: 'approve',
    status: 'draft',
    campaign_id: req.campaign_id,
    product_id: req.product_id,
    notes: req.brief ? `בריף מטלגרם: ${req.brief}`.slice(0, 500) : '',
    created_at: now,
    updated_at: now,
    chat_id: req.chat_id,
    app_url: req.app_url,
    ai_used: variants.length > 0,
    ai_error: aiError,
    alternatives,
  },
}];
